import{_ as o,o as d,c as a,a2 as c}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"声音驱动","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/driver-snd.md","filePath":"zh/l1/driver-snd.md"}'),t={name:"zh/l1/driver-snd.md"};function i(r,e,l,s,n,u){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="声音驱动" tabindex="-1">声音驱动 <a class="header-anchor" href="#声音驱动" aria-label="Permalink to &quot;声音驱动&quot;">​</a></h1><p>一个音频家族如何加入声音服务。</p><h2 id="模型-3-0-0" tabindex="-1">模型（3.0.0） <a class="header-anchor" href="#模型-3-0-0" aria-label="Permalink to &quot;模型（3.0.0）&quot;">​</a></h2><ul><li>驱动住在 <code>ocos/drivers/audio/</code> - 每个家族一个文件：HDA （<code>drv_audio_hda.c</code>）、AC&#39;97、SB16、ES1370、virtio-snd；USB 音频挂在 USB 类驱动上（<code>drv_usb_audio.c</code>）。</li><li>身份：<code>OC_DRIVER_DECL(&quot;snd&quot;, &quot;hda&quot;, &amp;g_snd_probe_hda, &quot;Intel HD Audio&quot;)</code> - 与其他所有类相同的收集器。</li><li>设备表 + 混音器 + 回放引擎住在声音服务 （<code>ocos/services/audio/</code>）里：设备注册表 （<code>driver_snd_device_t</code>，名字/声道/采样率/音量）、音调合成器 （<code>driver_snd_make_tone</code> - <code>play</code> 背后的 440 Hz 测试音）、 以及 L1SVC 类别 4 表面。</li></ul><h2 id="服务表面-17-个操作" tabindex="-1">服务表面（17 个操作） <a class="header-anchor" href="#服务表面-17-个操作" aria-label="Permalink to &quot;服务表面（17 个操作）&quot;">​</a></h2><p><code>sound</code>（设备总览）、按驱动的状态（<code>hda</code>、<code>ac97</code>、<code>sb16</code>、 <code>es1370</code>、<code>virtiosnd</code>、<code>usbaudio</code>）、<code>play [device] [rate]</code> （测试音）、<code>volume [device] [0-100]</code>，以及自检家族 （<code>hda_test</code> .. <code>sample_rate_test</code>、RW 回环、采样率精度探针）。</p><h2 id="代码里携带的防御性注记" tabindex="-1">代码里携带的防御性注记 <a class="header-anchor" href="#代码里携带的防御性注记" aria-label="Permalink to &quot;代码里携带的防御性注记&quot;">​</a></h2><ul><li>一张报告 <code>channels == 0</code> 的卡不得在帧数行除零（BUG-0243： 服务报告 0 帧，play 如实报告设备错误）。</li><li><code>sound-tool</code> 向导在数字触达服务之前先做仅数字校验 - 新增 字段时保持这个分层。</li></ul><h2 id="一个新家族长什么样" tabindex="-1">一个新家族长什么样 <a class="header-anchor" href="#一个新家族长什么样" aria-label="Permalink to &quot;一个新家族长什么样&quot;">​</a></h2><ol><li><code>ocos/drivers/audio/drv_audio_&lt;fam&gt;.{c,h}</code> - 探测、描述符 解析、PCM 流设置。</li><li><code>OC_DRIVER_DECL(&quot;snd&quot;, &quot;&lt;fam&gt;&quot;, &amp;ops, &quot;description&quot;)</code>。</li><li>一个状态操作（只许追加编号）+ <code>sound-tool</code> 经典表行 + 按驱动 的子菜单项。</li></ol><h2 id="消费者契约" tabindex="-1">消费者契约 <a class="header-anchor" href="#消费者契约" aria-label="Permalink to &quot;消费者契约&quot;">​</a></h2><p><code>sound-tool sound</code> -&gt; <code>sys_l1svc(SND, SOUND, ...)</code>；向导与脚本 读英文设备行；<code>play</code> 的 usage （<code>play [device] [rate 4000-96000]</code>）是稳定拼法。</p>',12)])])}const p=o(t,[["render",i]]);export{h as __pageData,p as default};
